# 提取f-string前缀部分并重建为JoinedStr values
fstring_parts = []
if cond_val_start is not None and cond_val_start > 0:
    _prefix_instrs = cond_block_instrs[:cond_val_start]
    _stack = []
    for pi in _prefix_instrs:
        if pi.opname.startswith('LOAD_'):
            _pe = self.expr_reconstructor.reconstruct([pi])
            if _pe:
                _stack.append(_pe)
        elif pi.opname == 'FORMAT_VALUE':
            if _stack:
                _val = _stack.pop()
                flags = pi.arg if pi.arg is not None else 0
                # [Round6-12/13/14] FORMAT_VALUE flags: bit0-1 = conversion
                # (0=none, 1=str, 2=repr, 3=ascii), bit2 = has format_spec.
                # 旧 elif 链 `if flags & 1: 1 elif flags & 2: 2 elif flags & 3: 3`
                # 对 !a (flags=3) 错误返回 1（3&1=1 先命中）。flags&3 是 2-bit
                # 数值，应直接掩码取值，不能用 elif 链。
                conversion = flags & 3
                format_spec = None
                if flags & 4 and _stack:
                    _fs = _stack.pop()
                    if isinstance(_fs, dict) and _fs.get('type') == 'Constant':
                        format_spec = _fs.get('value')
                    else:
                        format_spec = _fs
                _stack.append({
                    'type': 'FormattedValue',
                    'value': _val,
                    'conversion': conversion,
                    'format_spec': format_spec,
                })
        elif pi.opname == 'LOAD_CONST':
            _stack.append({'type': 'Constant', 'value': pi.argval})
    fstring_parts = _stack
# ternary是最后一个FormattedValue（merge_block的FORMAT_VALUE格式化它）
fstring_parts.append({
    'type': 'FormattedValue',
    'value': ternary_expr,
    'conversion': 0,
    'format_spec': None,
})
if region.merge_block:
    _mb_instrs = [i for i in region.merge_block.instructions
                  if i.opname not in ('RESUME', 'NOP', 'CACHE', 'PUSH_NULL')]
    _after_fv = False
    for _mi in _mb_instrs:
        if _mi.opname == 'FORMAT_VALUE':
            _after_fv = True
            continue
        if _after_fv:
            if _mi.opname == 'LOAD_CONST':
                fstring_parts.append({
                    'type': 'Constant', 'value': _mi.argval,
                })
            elif _mi.opname == 'BUILD_STRING':
                break
joined_str = {
    'type': 'JoinedStr',
    'values': fstring_parts,
}
# 检查merge_block是否有RETURN_VALUE
has_return = False
if region.merge_block:
    for instr in region.merge_block.instructions:
        if instr.opname in ('RETURN_VALUE', 'RETURN_CONST'):
            has_return = True
            break
if has_return:
    results.append({'type': 'Return', 'value': joined_str})
else:
    results.append({'type': 'Expr', 'value': joined_str})
